import re

def parse_duration(text: str) -> float:
    # Check if text starts with 'P'
    if not text or text[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    # Check for trailing whitespace/newlines
    if text != text.strip():
        raise ValueError("Duration must not have leading/trailing whitespace")

    # Remove the leading 'P'
    text = text[1:]

    # Check for invalid characters (only ASCII digits, letters W, D, H, M, S, T and . or ,)
    if not re.match(r'^[0-9WDHMS.,T]*$', text):
        raise ValueError("Invalid characters in duration")

    # Split into date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    # Parse date part (weeks or days)
    weeks = 0
    days = 0
    day_has_fraction = False

    if date_part:
        if 'W' in date_part:
            if 'D' in date_part:
                raise ValueError("Cannot have both weeks and days")
            if time_part:
                raise ValueError("Weeks cannot be combined with time components")
            match = re.match(r'^(\d+(?:[.,]\d+)?)W$', date_part)
            if not match:
                raise ValueError("Invalid week format")
            weeks = float(match.group(1).replace(',', '.'))
        elif 'D' in date_part:
            match = re.match(r'^(\d+(?:[.,]\d+)?)D$', date_part)
            if not match:
                raise ValueError("Invalid day format")
            day_str = match.group(1)
            if '.' in day_str or ',' in day_str:
                day_has_fraction = True
            days = float(day_str.replace(',', '.'))
        else:
            raise ValueError("Invalid date format")

    # Check if day has fraction and time part is present
    if day_has_fraction and time_part:
        raise ValueError("Day cannot have a decimal fraction if time components are present")

    # Parse time part (hours, minutes, seconds)
    hours = 0
    minutes = 0
    seconds = 0

    if time_part:
        # Only the last component (whichever is present) can have a decimal
        # Pattern: optional number H, optional number M, optional number S
        # where the last one present may have a decimal
        pattern = r'^(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?$'
        match = re.match(pattern, time_part)

        if not match:
            raise ValueError("Invalid time format")

        h_str = match.group(1)
        m_str = match.group(2)
        s_str = match.group(3)

        # Check that at least one time component is present
        if h_str is None and m_str is None and s_str is None:
            raise ValueError("At least one time component must be present after 'T'")

        # Validate decimal placement: only the last component can have a decimal
        if h_str is not None:
            if '.' in h_str or ',' in h_str:
                # H has decimal, so M and S must not be present
                if m_str is not None or s_str is not None:
                    raise ValueError("Only the last time component can have a decimal")
                hours = float(h_str.replace(',', '.'))
            else:
                hours = float(h_str)

        if m_str is not None:
            if '.' in m_str or ',' in m_str:
                # M has decimal, so S must not be present
                if s_str is not None:
                    raise ValueError("Only the last time component can have a decimal")
                minutes = float(m_str.replace(',', '.'))
            else:
                minutes = float(m_str)

        if s_str is not None:
            seconds = float(s_str.replace(',', '.'))

    # Check that at least one component was specified (either date or time part exists)
    if not date_part and not time_part:
        raise ValueError("At least one duration component must be present")

    # Convert to seconds
    total_seconds = (weeks * 7 * 86400) + (days * 86400) + (hours * 3600) + (minutes * 60) + seconds

    return total_seconds
